// Mastermind (Declarative): seat 0 codemaker, seat 1 codebreaker, one round.
// The secret code lives only in authoritative state; viewFor hides it from
// the codebreaker and spectators until the match is over.
// state.last_move is the animation record for the last accepted action,
// replaced on every accepted move. It is privacy-safe by construction:
// the setCode record is inert ({kind:'set'}, no code contents) and guess
// records carry only public piece ids and board positions (no colors),
// so viewFor can pass last_move through exactly like guesses/feedback.
function scoreGuess(code, guess) {
  let black = 0;
  const cr = [0, 0, 0, 0, 0, 0], gr = [0, 0, 0, 0, 0, 0];
  for (let i = 0; i < 4; i++) {
    if (code[i] === guess[i]) black++;
    else { cr[code[i]]++; gr[guess[i]]++; }
  }
  let white = 0;
  for (let c = 0; c < 6; c++) white += Math.min(cr[c], gr[c]);
  return { black: black, white: white };
}
function validCode(c) {
  return Array.isArray(c) && c.length === 4 &&
    c.every(v => Number.isInteger(v) && v >= 0 && v <= 5);
}
function clone(o) { return JSON.parse(JSON.stringify(o)); }
function payoutsFor(s, ctx) {
  if (!ctx.pot) return {};
  const humans = ctx.players.filter(p => p.kind === 'human' && p.active !== false);
  const winner = ctx.players[s.winner];
  const recipients = winner && winner.kind === 'human' && winner.active !== false ? [winner] : humans;
  const out = {};
  if (!recipients.length) return out;
  recipients.forEach((p, i) => {
    out[p.id] = Math.floor(ctx.pot / recipients.length) + (i < ctx.pot % recipients.length ? 1 : 0);
  });
  return out;
}
function randomCode(ctx) {
  return [0, 0, 0, 0].map(() => Math.floor(ctx.random() * 6));
}
// Last-move provenance helpers. Positions mirror the presentation layout
// in ui_code exactly: staged entry pegs sit on the palette board at
// x=44+i*44, y=36; guess pegs land on the main board at x=150+i*46,
// y=76+row*38; scoring feedback pegs land in the 2x2 cluster at
// x=400+(j%2)*24, y=rowY-10+floor(j/2)*20 and start from a supply bin at
// the palette's right end (x=520+j*20, y=36). Guess peg ids are
// g_<row>_<slot> and feedback peg ids f_<row>_<slot>: rows are
// append-only and slots fixed, so ids are stable and never shift.
function paletteSlotPos(i) { return { board: 'palette', position: { x: 44 + i * 44, y: 36 } }; }
function guessCellPos(row, i) { return { board: 'main', position: { x: 150 + i * 46, y: 76 + row * 38 } }; }
function feedbackSupplyPos(j) { return { board: 'palette', position: { x: 520 + j * 20, y: 36 } }; }
function feedbackCellPos(row, j) { const y = 76 + row * 38; return { board: 'main', position: { x: 400 + (j % 2) * 24, y: y - 10 + Math.floor(j / 2) * 20 } }; }
function guessRecord(row, black, white) {
  const pegs = [], feedback_pegs = [];
  for (let i = 0; i < 4; i++) pegs.push({ piece_id: 'g_' + row + '_' + i, from: paletteSlotPos(i), to: guessCellPos(row, i) });
  for (let j = 0; j < black + white; j++) feedback_pegs.push({ piece_id: 'f_' + row + '_' + j, from: feedbackSupplyPos(j), to: feedbackCellPos(row, j) });
  return { kind: 'guess', row: row, pegs: pegs, feedback_pegs: feedback_pegs };
}
const game = {
  newMatch(ctx) {
    const s = { phase: 'set', code: null, guesses: [], feedback: [], turn: 0, winner: -1, over: false, last_move: null };
    return { state: s, turn: [ctx.players[0].id] };
  },
  applyMove(state, id, move, ctx) {
    if (state.over) throw new InvalidMove('Illegal move');
    if (!move || typeof move !== 'object' || Array.isArray(move)) throw new InvalidMove('Illegal move');
    if (ctx.players[state.turn].id !== id) throw new InvalidMove('Illegal move');
    const want = state.phase === 'set' ? 'setCode' : state.phase === 'guess' ? 'guess' : null;
    if (!want || move.type !== want) throw new InvalidMove('Illegal move');
    if (Object.keys(move).length !== 2 || !validCode(move.code)) throw new InvalidMove('Illegal move');
    const s = clone(state);
    if (move.type === 'setCode') {
      s.code = move.code.slice();
      s.phase = 'guess';
      s.turn = 1;
      // Inert on purpose: the code must not appear in any view field,
      // including last_move, for the codebreaker or spectators.
      s.last_move = { kind: 'set' };
    } else {
      const f = scoreGuess(s.code, move.code);
      s.guesses.push(move.code.slice());
      s.feedback.push(f);
      s.last_move = guessRecord(s.guesses.length - 1, f.black, f.white);
      if (f.black === 4) { s.winner = 1; s.over = true; s.phase = 'over'; }
      else if (s.guesses.length >= 10) { s.winner = 0; s.over = true; s.phase = 'over'; }
    }
    return s.over
      ? { state: s, turn: null, payouts: payoutsFor(s, ctx) }
      : { state: s, turn: [ctx.players[s.turn].id] };
  },
  viewFor(state, id, ctx) {
    const s = clone(state);
    const seat = ctx.players.findIndex(p => p.id === id);
    // Only the codemaker (seat 0) sees the secret while play continues.
    // Once the match is over the code is revealed to everyone.
    // last_move needs no extra filtering: the 'set' record is inert and
    // 'guess' records hold only public ids/positions, never the code.
    if (!s.over && seat !== 0) s.code = null;
    return s;
  },
  randomMove(state, id, ctx) {
    return state.phase === 'set'
      ? { type: 'setCode', code: randomCode(ctx) }
      : { type: 'guess', code: randomCode(ctx) };
  },
  computerMove(state, id, ctx) {
    if (state.phase === 'set') return { type: 'setCode', code: randomCode(ctx) };
    // Guess only codes consistent with every feedback received so far.
    const cand = [];
    for (let a = 0; a < 6; a++) for (let b = 0; b < 6; b++)
      for (let c = 0; c < 6; c++) for (let d = 0; d < 6; d++) {
        const code = [a, b, c, d];
        let ok = true;
        for (let i = 0; i < state.guesses.length; i++) {
          const f = scoreGuess(code, state.guesses[i]);
          if (f.black !== state.feedback[i].black || f.white !== state.feedback[i].white) { ok = false; break; }
        }
        if (ok) cand.push(code);
      }
    const pick = cand.length ? cand[Math.floor(ctx.random() * cand.length)] : randomCode(ctx);
    return { type: 'guess', code: pick };
  }
};

declarative_ui.ui_code:
const SOURCE_STRINGS = {"title": "Mastermind", "status_set": "Codemaker: set the secret code", "status_guess": "Codebreaker: make a guess", "win_maker": "Codemaker wins", "win_breaker": "Codebreaker wins", "left": "{n} guesses left", "secret": "Secret code", "submit_code": "Set code", "submit_guess": "Guess", "reset": "Reset", "server_invalid": "Illegal move"};
// Mastermind presentation: a secret row plus ten guess rows on the main
// board, and a palette board shown interactively only to the acting viewer.
// The palette holds the four staged entry pegs (the peg for the slot being
// edited is marked selected) and six color targets for that slot, with ids
// slot<slot>-color-<color> that set the slot directly to that color; tapping
// one stages the color and advances the edit to the next slot (wrapping
// around, so any slot can be corrected). Submit sends the staged code as
// the one authoritative move. Pieces never declare actions: all
// interactivity is expressed through targets and controls.
const PEG_COLORS = ['#e53935', '#fb8c00', '#fdd835', '#43a047', '#1e88e5', '#8e24aa'];
const gameUI = {
  reduce(message, localState) {
    const m = message.type === 'ui_event' ? message.state_changed : message;
    const s = m.view || m.state;
    const strings = Object.assign({}, SOURCE_STRINGS, m.strings || {});
    const t = (key, args = {}) => (strings[key] || key).replace(/\{(\w+)\}/g, (_, k) => String(args[k] === undefined ? '' : args[k]));
    const active = m.status === 'ongoing' && !m.replay && m.acting_for_player_index !== null && m.acting_for_player_index !== undefined;
    let local = (localState && Array.isArray(localState.entry) && localState.entry.length === 4
      && localState.entry.every(v => Number.isInteger(v) && v >= 0 && v <= 5)
      && Number.isInteger(localState.slot) && localState.slot >= 0 && localState.slot <= 3
      && localState.move_count === m.move_count)
      ? { entry: localState.entry.slice(), slot: localState.slot, move_count: m.move_count }
      : { entry: [0, 0, 0, 0], slot: 0, move_count: m.move_count };
    // Apply the event to the staged entry BEFORE building the scene, so the
    // returned scene already shows the updated staging.
    let makeMove = null;
    if (message.type === 'ui_event' && active && message.event && message.event.type === 'tap') {
      const e = message.event;
      if (e.id === 'submit') {
        makeMove = { type: s.phase === 'set' ? 'setCode' : 'guess', code: local.entry.slice() };
      } else {
        const hit = /^slot(\d)-color-(\d)$/.exec(e.id || '');
        if (hit) {
          const entry = local.entry.slice();
          entry[Number(hit[1])] = Number(hit[2]);
          local = { entry: entry, slot: (Number(hit[1]) + 1) % 4, move_count: m.move_count };
        }
      }
    }
    const pieces = [], targets = [], controls = [], labels = [];
    labels.push({ id: 'title', text: t('title'), x: 24, y: 14, font_size: 26 });
    const status = s.over
      ? (s.winner === 1 ? t('win_breaker') : t('win_maker'))
      : (s.phase === 'set' ? t('status_set') : t('status_guess'));
    labels.push({ id: 'status', text: status, x: 24, y: 48, font_size: 18 });
    labels.push({ id: 'left', text: t('left', { n: 10 - s.guesses.length }), x: 430, y: 48, font_size: 16 });
    labels.push({ id: 'secret_label', text: t('secret'), x: 24, y: 92, font_size: 15 });
    const known = s.code !== null && s.code !== undefined;
    for (let i = 0; i < 4; i++) {
      pieces.push({ id: 'secret_' + i, type: known ? 'c' + s.code[i] : 'hidden', board: 'main', position: { x: 150 + i * 46, y: 30 }, text: known ? '' : '?', actions: [] });
    }
    s.guesses.forEach((g, r) => {
      const y = 76 + r * 38;
      labels.push({ id: 'row_' + r, text: String(r + 1), x: 30, y: 84 + y - 8, font_size: 14 });
      g.forEach((c, i) => pieces.push({ id: 'g_' + r + '_' + i, type: 'c' + c, board: 'main', position: { x: 150 + i * 46, y: y }, text: '', actions: [] }));
      const f = s.feedback[r];
      const kinds = [];
      for (let b = 0; b < f.black; b++) kinds.push('fb_black');
      for (let w = 0; w < f.white; w++) kinds.push('fb_white');
      while (kinds.length < 4) kinds.push('fb_empty');
      kinds.forEach((kind, j) => pieces.push({ id: 'f_' + r + '_' + j, type: kind, board: 'main', position: { x: 400 + (j % 2) * 24, y: y - 10 + Math.floor(j / 2) * 20 }, text: '', actions: [] }));
    });
    if (active) {
      for (let i = 0; i < 4; i++) {
        pieces.push({ id: 'slot_' + i, type: 'c' + local.entry[i], board: 'palette', position: { x: 44 + i * 44, y: 36 }, text: '', actions: [], selected: local.slot === i });
      }
      labels.push({ id: 'cur_slot', text: String(local.slot + 1), x: 222, y: 567, font_size: 13 });
      for (let c = 0; c < 6; c++) {
        targets.push({
          id: 'slot' + local.slot + '-color-' + c, board: 'palette',
          position: { x: 240 + c * 57, y: 36 },
          color: PEG_COLORS[c],
          aria_label: 'Slot ' + (local.slot + 1) + ' color ' + (c + 1)
        });
      }
      controls.push({ id: 'submit', kind: 'button', label: s.phase === 'set' ? t('submit_code') : t('submit_guess') });
    }
    const scene = { pieces, targets, controls, labels };
    const out = { scene, local_state: local };
    if (makeMove) out.make_move = makeMove;
    return out;
  },
  // Last-move animation. Guess pegs fly from their palette staging slots
  // (the supply positions the server records) to the new row's cells in
  // placement order — left to right, 350 ms each — then the scoring
  // feedback pegs (blacks then whites, in scene slot order) fly from
  // the palette supply bin to the feedback cluster, 250 ms each. The
  // fb_empty placeholders are not placed pegs and are not animated.
  // Piece ids are stable by construction: guess pegs are
  // g_<row>_<slot> and feedback pegs f_<row>_<slot>, keyed by the
  // append-only row and the fixed slot, so an id never shifts to a
  // different peg. The code-setting record is inert ({kind:'set'},
  // no code contents) and yields no motion; a view from older pinned
  // rules without a last_move property keeps the host fallback (null).
  getLastMoveAnimations(view, scene) {
    if (!Object.prototype.hasOwnProperty.call(view, 'last_move')) return null;
    const move = view.last_move;
    if (!move || move.kind !== 'guess' || !Array.isArray(move.pegs)) return [];
    const byId = {};
    (scene.pieces || []).forEach(p => { byId[p.id] = p; });
    const out = [];
    const add = (peg, duration) => {
      const piece = byId[peg.piece_id];
      if (!piece) return;
      out.push({ piece_id: peg.piece_id, duration_ms: duration, path: [
        { board: peg.from.board, position: { x: peg.from.position.x, y: peg.from.position.y } },
        { board: piece.board, position: { x: piece.position.x, y: piece.position.y } }
      ] });
    };
    move.pegs.forEach(peg => add(peg, 350));
    (move.feedback_pegs || []).forEach(peg => add(peg, 250));
    return out;
  }
};
